mapper.select:
SELECT *
FROM bi_indicator
WHERE is_deleted = 0

    AND system_id = #{systemId}


    AND cat_id = #{catId}


    AND zb_name LIKE CONCAT('%', #{zbName}, '%')


    AND zb_code LIKE CONCAT('%', #{zbCode}, '%')


    AND status = #{status}

ORDER BY parent_zb_id ASC, zb_code ASC

